public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }
    Set<Integer> set = new HashSet<>();
    int hash = 0;
    int mask = (1 << k) - 1;
    for (int i = 0; i < s.length(); i++) {
        hash = ((hash & mask) << 1) + (s.charAt(i) - '0');
        if (i >= k - 1) {
            set.add(hash);
        }
    }
    return set.size() == (1 << k);
}

