public int minInsertions(String s) {
    int open = 0; // To count the number of open parentheses needed
    int insertions = 0; // To count the number of insertions made

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++; // Increment open count for an open parenthesis
        } else {
            // If we encounter a closing parenthesis
            if (open > 0) {
                open--; // Match it with an open parenthesis if available
            } else {
                insertions++; // Otherwise, insert a matching open parenthesis
            }
            // Check for a pair of closing parentheses
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next closing parenthesis as it's matched
            } else {
                insertions++; // Insert a matching closing parenthesis
            }
        }
    }

    // Add any remaining open parentheses needed
    insertions += open * 2;

    return insertions;
}

