public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;

    for (int i = 0; i < n; i++) {
        while (top != -1 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top]];
            top--;
            int left = top == -1 ? -1 : stack[top];
            maxArea = Math.max(maxArea, (i - 1 - left) * height);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top]];
        top--;
